/*
 * A023113  Squares that remain square when the digit 6 is appended.
 * https://oeis.org/A023113
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = square of the nth smallest positive integer y solving x²
 *            – 10·y² = 6. The y‑values are generated by merging two
 *            interleaved recurrence sequences derived from (4+√10)(19+6√10)^k
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 7, u64 n <= 13, u128 n <= 15,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Handle the first two terms directly. */
    if (n == 1) return (seq_t)1;     /* 1²  */
    if (n == 2) return (seq_t)25;    /* 5²  */

    /* Sequence A: 1, 43, 1633, ...  (y values) */
    seq_t prev1 = (seq_t)1;
    seq_t curr1 = (seq_t)43;          /* second term of this sequence */

    /* Sequence B: 5, 191, 7253, ...  (y values) */
    seq_t prev2 = (seq_t)5;
    seq_t curr2 = (seq_t)191;         /* second term of this sequence */

    seq_t y = 0;                      /* current y value to be squared */

    /* We already produced the first two terms; generate remaining ones. */
    for (idx_t i = 3; i <= n; ++i)
    {
        if (curr1 <= curr2)
        {
            y = curr1;
            /* advance sequence A */
            seq_t next = (seq_t)38 * curr1 - prev1;
            prev1 = curr1;
            curr1 = next;
        }
        else
        {
            y = curr2;
            /* advance sequence B */
            seq_t next = (seq_t)38 * curr2 - prev2;
            prev2 = curr2;
            curr2 = next;
        }
    }

    /* Return y squared (the required term of the sequence). */
    return y * y;
}
